import pytest
import torch

import flag_gems

from . import accuracy_utils as utils

# Custom shapes for fractional_max_pool3d: (batch, channels, depth, height, width), kernel_size, output_size
FRACTIONAL_MAXPOOL3D_CONFIGS = [
    # Classic case: 2x2x2 kernel, output size halved
    ((4, 3, 8, 32, 32), 2, (4, 16, 16)),
    # Different output sizes
    ((8, 16, 8, 28, 28), 2, (4, 14, 14)),
    # Test different output sizes
    ((2, 4, 8, 20, 20), 2, (4, 10, 10)),
    # Larger case
    ((1, 64, 8, 56, 56), 2, (4, 28, 28)),
    # Small spatial
    ((2, 8, 4, 16, 16), 2, (2, 8, 8)),
    # Non-square output
    ((2, 8, 8, 16, 20), 2, (4, 8, 10)),
]


@pytest.mark.fractional_max_pool3d
@pytest.mark.parametrize(
    "shape, kernel_size, output_size", FRACTIONAL_MAXPOOL3D_CONFIGS
)
@pytest.mark.parametrize("dtype", utils.FLOAT_DTYPES)
def test_accuracy_fractional_max_pool3d(shape, kernel_size, output_size, dtype):
    inp = torch.randn(shape, dtype=dtype, device=flag_gems.device, requires_grad=True)
    ref_inp = utils.to_reference(inp, True)

    # Use the same random_samples for both to ensure identical pooling regions.
    N, C = shape[0], shape[1]
    random_samples = torch.rand(N, C, 3, dtype=torch.float32, device=flag_gems.device)
    ref_random_samples = random_samples.to(device=ref_inp.device, dtype=ref_inp.dtype)

    ref_out, ref_indices = torch.nn.functional.fractional_max_pool3d(
        ref_inp,
        kernel_size=kernel_size,
        output_size=output_size,
        return_indices=True,
        _random_samples=ref_random_samples,
    )

    res_out, res_indices = flag_gems.fractional_max_pool3d(
        inp,
        kernel_size=kernel_size,
        output_size=output_size,
        _random_samples=random_samples,
    )

    utils.gems_assert_close(res_out, ref_out, dtype)
    # Indices should match exactly since we use the same random_samples
    torch.testing.assert_close(res_indices.to(ref_indices.device), ref_indices)
